'use client'

import { useState, type ReactNode } from 'react'
import { useForm } from 'react-hook-form'
import { yupResolver } from '@hookform/resolvers/yup'
import * as yup from 'yup'
import { CheckCircle2, MessageCircle, Send } from 'lucide-react'

import { Input } from '@/components/ui/input'
import { Textarea } from '@/components/ui/textarea'
import { AccentButton } from '@/components/library/primitives/AccentButton'
import { EyebrowHeading } from '@/components/library/primitives/EyebrowHeading'
import { getAccentTone, type AccentTone } from '@/components/library/primitives/accentTones'
import { cn } from '@/lib/utils'

const contactSchema = yup.object({
  name: yup.string().required('Nome é obrigatório'),
  email: yup.string().email('E-mail inválido').required('E-mail é obrigatório'),
  phone: yup.string().required('Telefone é obrigatório'),
  subject: yup.string().required('Assunto é obrigatório'),
  message: yup.string().required('Mensagem é obrigatória'),
})

export type ContactChannelsFormData = yup.InferType<typeof contactSchema>

export type ContactChannel = {
  label: string
  value: string
  icon: ReactNode
  href?: string
  external?: boolean
}

export type ContactChannelsSectionProps = {
  title: string
  onSubmit: (data: ContactChannelsFormData) => Promise<void> | void
  channels?: readonly ContactChannel[]
  eyebrow?: string
  description?: string
  formTitle?: string
  channelsTitle?: string
  channelsDescription?: string
  whatsapp?: { href: string; label?: string }
  successTitle?: string
  successDescription?: string
  layout?: 'cards' | 'joined'
  tone?: AccentTone
  className?: string
}

const fields = [
  { name: 'name', label: 'Nome', placeholder: 'Seu nome completo', type: 'text' },
  { name: 'email', label: 'E-mail', placeholder: 'Seu e-mail', type: 'email' },
  { name: 'phone', label: 'Telefone', placeholder: 'Seu telefone', type: 'tel' },
  { name: 'subject', label: 'Assunto', placeholder: 'Assunto da mensagem', type: 'text' },
] as const

/** Seção de contato com formulário validado (react-hook-form + yup) e lista de canais. */
export function ContactChannelsSection({
  title,
  onSubmit,
  channels = [],
  eyebrow,
  description,
  formTitle,
  channelsTitle = 'Informações de contato',
  channelsDescription,
  whatsapp,
  successTitle = 'Mensagem enviada',
  successDescription = 'Obrigado pelo contato. Nossa equipe retornará em breve.',
  layout = 'cards',
  tone = 'glow',
  className,
}: ContactChannelsSectionProps) {
  const t = getAccentTone(tone)
  const isGlow = tone === 'glow'
  const joined = layout === 'joined'
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [isSubmitted, setIsSubmitted] = useState(false)
  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm<ContactChannelsFormData>({ resolver: yupResolver(contactSchema) })

  const submit = async (data: ContactChannelsFormData): Promise<void> => {
    setSubmitError(null)
    try {
      await onSubmit(data)
      setIsSubmitted(true)
      reset()
    } catch {
      setSubmitError('Não foi possível enviar sua mensagem. Tente novamente.')
    }
  }

  const label = cn('mb-2 block text-[0.65rem] uppercase tracking-[0.2em]', t.muted)
  const field = cn('h-12', t.input)
  const darkPanel = joined && tone === 'industrial'
  const channelText = darkPanel
    ? {
        label: 'text-slate-400',
        value: 'text-white',
        icon: 'text-amber-500',
        border: 'border-white/10',
      }
    : { label: t.muted, value: t.strong, icon: t.accent, border: t.border }

  return (
    <section className={cn('w-full', t.section, className)}>
      <div className="container py-14 lg:py-16">
        <EyebrowHeading
          tone={tone}
          eyebrow={eyebrow}
          title={title}
          description={description}
          layout="split"
          className="mb-10 lg:mb-12"
        />

        {isSubmitted ? (
          <div
            className={cn(
              'mx-auto max-w-2xl border px-8 py-14 text-center sm:px-12',
              t.panel,
              t.border,
              isGlow && 'rounded-xl',
            )}
            role="status"
          >
            <CheckCircle2 className={cn('mx-auto mb-6 h-10 w-10', t.accent)} aria-hidden />
            <h3 className={cn('text-3xl', t.heading, isGlow && 'mx-auto')}>{successTitle}</h3>
            <p className={cn('mt-4 text-base leading-relaxed', t.body)}>{successDescription}</p>
            <AccentButton
              tone={tone}
              onClick={() => setIsSubmitted(false)}
              icon={<Send className="h-4 w-4" />}
              className="mx-auto mt-8"
            >
              Enviar nova mensagem
            </AccentButton>
          </div>
        ) : (
          <div
            className={cn(
              'grid grid-cols-1 lg:grid-cols-12',
              joined ? cn('border', t.border) : 'gap-10 lg:gap-12',
            )}
          >
            <div
              className={cn(
                'p-6 sm:p-8 lg:col-span-7 lg:p-10',
                t.panel,
                !joined && cn('border', t.border, isGlow && 'rounded-xl'),
              )}
            >
              {formTitle ? <h3 className={cn('mb-6 text-2xl', t.heading)}>{formTitle}</h3> : null}
              <form onSubmit={handleSubmit(submit)} className="space-y-5" noValidate>
                <div className="grid gap-5 sm:grid-cols-2">
                  {fields.map((item) => {
                    const error = errors[item.name]?.message
                    const id = `contact-${item.name}`
                    return (
                      <div key={item.name}>
                        <label htmlFor={id} className={label}>
                          {item.label}
                        </label>
                        <Input
                          id={id}
                          type={item.type}
                          placeholder={item.placeholder}
                          aria-invalid={Boolean(error)}
                          aria-describedby={error ? `${id}-error` : undefined}
                          className={field}
                          {...register(item.name)}
                        />
                        {error ? (
                          <p id={`${id}-error`} className={cn('mt-1.5 text-sm', t.error)}>
                            {error}
                          </p>
                        ) : null}
                      </div>
                    )
                  })}
                </div>
                <div>
                  <label htmlFor="contact-message" className={label}>
                    Mensagem
                  </label>
                  <Textarea
                    id="contact-message"
                    rows={6}
                    placeholder="Descreva sua necessidade"
                    aria-invalid={Boolean(errors.message)}
                    aria-describedby={errors.message ? 'contact-message-error' : undefined}
                    className={cn(t.input, 'min-h-[160px] resize-y py-3')}
                    {...register('message')}
                  />
                  {errors.message?.message ? (
                    <p id="contact-message-error" className={cn('mt-1.5 text-sm', t.error)}>
                      {errors.message.message}
                    </p>
                  ) : null}
                </div>
                {submitError ? (
                  <p className={cn('text-sm', t.error)} role="alert">
                    {submitError}
                  </p>
                ) : null}
                <div className="flex justify-center pt-1">
                  <AccentButton
                    tone={tone}
                    type="submit"
                    disabled={isSubmitting}
                    icon={<Send className="h-4 w-4" />}
                  >
                    {isSubmitting ? 'Enviando...' : 'Enviar mensagem'}
                  </AccentButton>
                </div>
              </form>
            </div>

            <div
              className={cn(
                'lg:col-span-5',
                joined &&
                  cn(
                    'border-t p-7 sm:p-8 lg:border-l lg:border-t-0 lg:p-10',
                    t.border,
                    darkPanel ? 'bg-slate-950 text-white' : t.alt,
                  ),
              )}
            >
              <h3
                className={cn(
                  'text-2xl',
                  darkPanel ? 'font-semibold uppercase tracking-wide text-white' : t.heading,
                )}
              >
                {channelsTitle}
              </h3>
              {channelsDescription ? (
                <p
                  className={cn(
                    'mt-4 text-sm leading-relaxed lg:text-base',
                    darkPanel ? 'text-slate-300' : t.body,
                  )}
                >
                  {channelsDescription}
                </p>
              ) : null}

              {channels.length ? (
                <ul
                  className={cn(
                    'mt-8 divide-y',
                    channelText.border,
                    darkPanel ? 'divide-white/10 border-y' : t.divide,
                    !joined && cn('border', t.panel, isGlow && 'rounded-xl'),
                    joined && !darkPanel && 'border-y',
                  )}
                >
                  {channels.map((channel) => {
                    const content = (
                      <>
                        <span
                          className={cn(
                            'mt-0.5 h-5 w-5 shrink-0 [&>svg]:h-5 [&>svg]:w-5',
                            channelText.icon,
                          )}
                          aria-hidden
                        >
                          {channel.icon}
                        </span>
                        <span>
                          <span
                            className={cn(
                              'block text-[0.65rem] uppercase tracking-[0.18em]',
                              channelText.label,
                            )}
                          >
                            {channel.label}
                          </span>
                          <span
                            className={cn(
                              'mt-1 block text-sm font-medium sm:text-base',
                              channelText.value,
                            )}
                          >
                            {channel.value}
                          </span>
                        </span>
                      </>
                    )
                    return (
                      <li key={channel.label} className={cn(joined ? 'py-5' : 'p-5 sm:p-6')}>
                        {channel.href ? (
                          <a
                            href={channel.href}
                            target={channel.external ? '_blank' : undefined}
                            rel={channel.external ? 'noopener noreferrer' : undefined}
                            className={cn(
                              'flex items-start gap-4 transition-opacity hover:opacity-80',
                              t.focus,
                            )}
                          >
                            {content}
                          </a>
                        ) : (
                          <div className="flex items-start gap-4">{content}</div>
                        )}
                      </li>
                    )
                  })}
                </ul>
              ) : null}

              {whatsapp ? (
                <AccentButton
                  tone={darkPanel ? 'industrial-dark' : tone}
                  href={whatsapp.href}
                  external
                  icon={<MessageCircle className="h-4 w-4" />}
                  className="mt-8"
                >
                  {whatsapp.label ?? 'Conversar no WhatsApp'}
                </AccentButton>
              ) : null}
            </div>
          </div>
        )}
      </div>
    </section>
  )
}

import type { MouseEventHandler, ReactNode } from 'react'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

import type { AccentTone } from './accentTones'

export type AccentButtonProps = {
  children: ReactNode
  href?: string
  tone?: AccentTone
  size?: 'md' | 'lg'
  icon?: ReactNode
  external?: boolean
  type?: 'button' | 'submit'
  disabled?: boolean
  onClick?: MouseEventHandler<HTMLElement>
  className?: string
}

const slideBase =
  'group relative inline-flex w-fit cursor-pointer items-center overflow-hidden rounded-sm font-semibold tracking-wide transition-all duration-500 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500 focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-60'

const slideSizes = {
  md: {
    root: 'h-12 p-1.5 ps-5 pe-14 text-sm hover:ps-14 hover:pe-5',
    icon: 'right-1.5 h-9 w-9 group-hover:right-[calc(100%-42px)]',
  },
  lg: {
    root: 'h-14 p-1 ps-6 pe-20 text-base hover:ps-20 hover:pe-6 md:text-lg',
    icon: 'right-1.5 h-11 w-11 group-hover:right-[calc(100%-50px)]',
  },
}

const toneClasses: Record<AccentTone, { root: string; icon: string }> = {
  glow: {
    root: 'inline-flex items-center justify-center gap-2 rounded-full border-2 border-[#7c39cf] bg-transparent px-4 py-2 font-semibold text-[#ae89ff] transition-[color,border-color,box-shadow,background-color] duration-300 hover:border-[#c642a5] hover:bg-gradient-to-r hover:from-[#86196b] hover:to-[#5327b3] hover:text-white hover:shadow-[0_0_8px_#c642a5] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#c642a5] focus-visible:ring-offset-2 focus-visible:ring-offset-[#121212] disabled:pointer-events-none disabled:opacity-60',
    icon: '',
  },
  industrial: {
    root: 'bg-slate-900 text-white hover:bg-amber-500 hover:text-slate-950',
    icon: 'bg-white text-slate-900 group-hover:bg-slate-950 group-hover:text-white',
  },
  'industrial-dark': {
    root: 'bg-amber-500 text-slate-950 hover:bg-white',
    icon: 'bg-white text-slate-950 group-hover:bg-slate-950 group-hover:text-white',
  },
}

/** Botão de ação dos templates: contorno com gradiente (glow) ou ícone deslizante (industrial). */
export function AccentButton({
  children,
  href,
  tone = 'glow',
  size = 'md',
  icon,
  external,
  type = 'button',
  disabled,
  onClick,
  className,
}: AccentButtonProps) {
  const styles = toneClasses[tone]
  const isGlow = tone === 'glow'
  const resolvedIcon = icon ?? <ArrowUpRight className="h-4 w-4 shrink-0" aria-hidden />
  const classes = isGlow
    ? cn(styles.root, size === 'lg' && 'px-6 py-3 text-lg', className)
    : cn(slideBase, slideSizes[size].root, styles.root, className)

  const content = isGlow ? (
    <>
      {icon}
      {children}
    </>
  ) : (
    <>
      <span className="relative z-10 transition-colors duration-500">{children}</span>
      <span
        className={cn(
          'absolute flex items-center justify-center rounded-full transition-all duration-500 group-hover:rotate-12',
          slideSizes[size].icon,
          styles.icon,
        )}
        aria-hidden
      >
        {resolvedIcon}
      </span>
    </>
  )

  if (href) {
    const isExternal = external ?? /^(https?:|mailto:|tel:)/.test(href)
    if (isExternal) {
      return (
        <a
          href={href}
          className={classes}
          onClick={onClick}
          target={href.startsWith('http') ? '_blank' : undefined}
          rel={href.startsWith('http') ? 'noopener noreferrer' : undefined}
        >
          {content}
        </a>
      )
    }
    return (
      <Link href={href} className={classes} onClick={onClick}>
        {content}
      </Link>
    )
  }

  return (
    <button type={type} className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  )
}

import type { ReactNode } from 'react'

import { cn } from '@/lib/utils'

import { getAccentTone, type AccentTone } from './accentTones'

export type EyebrowHeadingProps = {
  title: ReactNode
  eyebrow?: ReactNode
  description?: ReactNode
  tone?: AccentTone
  align?: 'left' | 'center'
  layout?: 'stacked' | 'split'
  size?: 'md' | 'lg'
  titleAs?: 'h1' | 'h2' | 'h3'
  action?: ReactNode
  className?: string
}

const titleSizes = {
  md: 'text-3xl leading-[1.15] sm:text-4xl lg:text-[2.5rem]',
  lg: 'text-3xl leading-[1.12] sm:text-4xl md:text-5xl lg:text-[3.25rem]',
}

/** Cabeçalho de seção com linha de destaque, título temático e descrição opcional ao lado. */
export function EyebrowHeading({
  title,
  eyebrow,
  description,
  tone = 'glow',
  align = 'left',
  layout = 'stacked',
  size = 'md',
  titleAs: Title = 'h2',
  action,
  className,
}: EyebrowHeadingProps) {
  const t = getAccentTone(tone)
  const centered = align === 'center'
  const split = layout === 'split' && !centered

  const line = <span className={cn('h-px w-8 shrink-0', t.line)} aria-hidden />

  return (
    <div
      className={cn(
        split && 'flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between',
        centered && 'mx-auto max-w-3xl text-center',
        className,
      )}
    >
      <div className={cn(split ? 'max-w-2xl' : centered ? '' : 'max-w-3xl')}>
        {eyebrow ? (
          <div className={cn('mb-4 flex items-center gap-3', centered && 'justify-center')}>
            {line}
            <span
              className={cn('text-[0.65rem] font-medium uppercase tracking-[0.28em]', t.accent)}
            >
              {eyebrow}
            </span>
            {centered ? line : null}
          </div>
        ) : null}
        <Title className={cn(t.heading, titleSizes[size], centered && 'mx-auto')}>{title}</Title>
        {!split && description ? (
          <p
            className={cn(
              'mt-5 max-w-2xl text-base leading-relaxed md:text-lg',
              t.body,
              centered && 'mx-auto',
            )}
          >
            {description}
          </p>
        ) : null}
        {!split && action ? (
          <div className={cn('mt-8 flex flex-wrap gap-3', centered && 'justify-center')}>
            {action}
          </div>
        ) : null}
      </div>
      {split && (description || action) ? (
        <div className="max-w-md space-y-5">
          {description ? (
            <p className={cn('text-sm leading-relaxed lg:text-base', t.body)}>{description}</p>
          ) : null}
          {action}
        </div>
      ) : null}
    </div>
  )
}

import * as React from 'react'

import { cn } from '@/lib/utils'

const Input = React.forwardRef<HTMLInputElement, React.ComponentProps<'input'>>(
  ({ className, type, ...props }, ref) => {
    return (
      <input
        type={type}
        className={cn(
          'flex h-9 w-full rounded-md border border-input bg-transparent px-3 py-1 text-base shadow-sm transition-colors file:border-0 file:bg-transparent file:text-sm file:font-medium file:text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 md:text-sm',
          className,
        )}
        ref={ref}
        {...props}
      />
    )
  },
)
Input.displayName = 'Input'

export { Input }

import * as React from 'react'

import { cn } from '@/lib/utils'

const Textarea = React.forwardRef<HTMLTextAreaElement, React.ComponentProps<'textarea'>>(
  ({ className, ...props }, ref) => {
    return (
      <textarea
        className={cn(
          'flex min-h-[60px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-base shadow-sm placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring disabled:cursor-not-allowed disabled:opacity-50 md:text-sm',
          className,
        )}
        ref={ref}
        {...props}
      />
    )
  },
)
Textarea.displayName = 'Textarea'

export { Textarea }

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}
